-- ============ 2. Les 28 croyances fondamentales ============
-- Remplace les 7 leçons génériques par les 28 articles de foi réels,
-- groupés selon les six sections officielles, avec leur référence.
UPDATE media SET lessons = '[{"number": 1, "title_fr": "1. Les Saintes Écritures", "title_mg": "1. Ny Soratra Masina", "reference": "2 Timothée 3:16-17", "section_fr": "La doctrine de Dieu", "section_mg": "Ny fampianarana momba an''Andriamanitra"}, {"number": 2, "title_fr": "2. La Trinité", "title_mg": "2. Ny Trinite", "reference": "Matthieu 28:19", "section_fr": "La doctrine de Dieu", "section_mg": "Ny fampianarana momba an''Andriamanitra"}, {"number": 3, "title_fr": "3. Le Père", "title_mg": "3. Andriamanitra Ray", "reference": "Jean 3:16", "section_fr": "La doctrine de Dieu", "section_mg": "Ny fampianarana momba an''Andriamanitra"}, {"number": 4, "title_fr": "4. Le Fils", "title_mg": "4. Andriamanitra Zanaka", "reference": "Jean 1:1-3, 14", "section_fr": "La doctrine de Dieu", "section_mg": "Ny fampianarana momba an''Andriamanitra"}, {"number": 5, "title_fr": "5. Le Saint-Esprit", "title_mg": "5. Ny Fanahy Masina", "reference": "Jean 14:16-17", "section_fr": "La doctrine de Dieu", "section_mg": "Ny fampianarana momba an''Andriamanitra"}, {"number": 6, "title_fr": "6. La création", "title_mg": "6. Ny Famoronana", "reference": "Genèse 1:1-2", "section_fr": "La doctrine de l''homme", "section_mg": "Ny fampianarana momba ny olombelona"}, {"number": 7, "title_fr": "7. La nature de l''homme", "title_mg": "7. Ny Toetran''ny Olombelona", "reference": "Genèse 1:26-28", "section_fr": "La doctrine de l''homme", "section_mg": "Ny fampianarana momba ny olombelona"}, {"number": 8, "title_fr": "8. Le grand conflit", "title_mg": "8. Ny Ady Lehibe", "reference": "Apocalypse 12:4-9", "section_fr": "La doctrine de l''homme", "section_mg": "Ny fampianarana momba ny olombelona"}, {"number": 9, "title_fr": "9. Vie, mort et résurrection du Christ", "title_mg": "9. Ny Fiainana, Fahafatesana ary Fitsanganan''i Kristy", "reference": "Jean 3:16", "section_fr": "La doctrine du salut", "section_mg": "Ny fampianarana momba ny famonjena"}, {"number": 10, "title_fr": "10. L''expérience du salut", "title_mg": "10. Ny Fanandramana ny Famonjena", "reference": "Éphésiens 2:8-10", "section_fr": "La doctrine du salut", "section_mg": "Ny fampianarana momba ny famonjena"}, {"number": 11, "title_fr": "11. Croître en Christ", "title_mg": "11. Ny Fitomboana ao amin''i Kristy", "reference": "Colossiens 2:6-15", "section_fr": "La doctrine du salut", "section_mg": "Ny fampianarana momba ny famonjena"}, {"number": 12, "title_fr": "12. L''Église", "title_mg": "12. Ny Fiangonana", "reference": "Éphésiens 1:22-23", "section_fr": "La doctrine de l''Église", "section_mg": "Ny fampianarana momba ny Fiangonana"}, {"number": 13, "title_fr": "13. Le reste et sa mission", "title_mg": "13. Ny Sisa sy ny Iraka Nampanaovina Azy", "reference": "Apocalypse 14:6-12", "section_fr": "La doctrine de l''Église", "section_mg": "Ny fampianarana momba ny Fiangonana"}, {"number": 14, "title_fr": "14. L''unité du corps du Christ", "title_mg": "14. Ny Firaisana ao amin''ny Vatan''i Kristy", "reference": "Éphésiens 4:1-6", "section_fr": "La doctrine de l''Église", "section_mg": "Ny fampianarana momba ny Fiangonana"}, {"number": 15, "title_fr": "15. Le baptême", "title_mg": "15. Ny Batisa", "reference": "Romains 6:1-6", "section_fr": "La doctrine de l''Église", "section_mg": "Ny fampianarana momba ny Fiangonana"}, {"number": 16, "title_fr": "16. La sainte cène", "title_mg": "16. Ny Fanasan''ny Tompo", "reference": "1 Corinthiens 11:23-30", "section_fr": "La doctrine de l''Église", "section_mg": "Ny fampianarana momba ny Fiangonana"}, {"number": 17, "title_fr": "17. Les dons spirituels et les ministères", "title_mg": "17. Ny Fanomezam-pahasoavana sy ny Fanompoana", "reference": "1 Corinthiens 12:9-11", "section_fr": "La doctrine de l''Église", "section_mg": "Ny fampianarana momba ny Fiangonana"}, {"number": 18, "title_fr": "18. Le don de prophétie", "title_mg": "18. Ny Fanomezam-pahasoavana Faminaniana", "reference": "Apocalypse 12:17", "section_fr": "La doctrine de l''Église", "section_mg": "Ny fa